import React from "react";
import { Link } from "react-router-dom";

function Navbar() {
  return (
    <nav style={styles.navbar}>
      <div style={styles.logo}>
        Sasurie College Of Engineering (Auton0)
      </div>

      <div style={styles.links}>
        <Link to="/" style={styles.link}>Register</Link>

        <Link to="/admin">
          <button style={styles.adminBtn}>Admin Login</button>
        </Link>
      </div>
    </nav>
  );
}

const styles = {
  navbar: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    background: "#222",
    padding: "12px 20px",
    color: "white"
  },

  logo: {
    fontSize: "18px",
    fontWeight: "bold"
  },

  links: {
    display: "flex",
    gap: "15px",
    alignItems: "center"
  },

  link: {
    textDecoration: "none",
    color: "white"
  },

  adminBtn: {
    padding: "6px 12px",
    border: "none",
    background: "#00b894",
    color: "white",
    borderRadius: "4px",
    cursor: "pointer"
  }
};

export default Navbar;
